FUNCTION_BLOCK FlexibleProcessingControl
VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL;
    conveyorRight : BOOL;
END_VAR
VAR
    state : INT := 0; (* 0 idle, 1 moving, 2 wait complete, 3 done *)
    stepIndex : USINT := 1;
    currentStation : USINT := 1;
    targetStation : USINT := 5;
    lastStation2Complete : BOOL := FALSE;
    lastStation3Complete : BOOL := FALSE;
    lastStation4Complete : BOOL := FALSE;
    start2 : BOOL := FALSE;
    start3 : BOOL := FALSE;
    start4 : BOOL := FALSE;
    startCmd : BOOL := FALSE;
END_VAR
